Definition rng63 (r : option (Z * Z)) : option (PrimInt63.int * PrimInt63.int) :=
  match r with
  | Some (lo, hi) => match zb lo, zb hi with Some x, Some y => Some (x, y) | _, _ => None end
  | None => None
  end.

