Fixpoint all_eval_toSD (s : expr) (d : dex) (v lo : Z) (cnt : nat) : bool :=
  match cnt with
  | O => true
  | S c => match evalD s [] d (wrap64 lo) with
           | Some w => if Z.eqb w v then all_eval_toSD s d v (lo + 1) c else false
           | None => false
           end
  end.
