Definition CINV (a : list (expr * Z * Z)) (done : list expr) : Prop :=
  List.NoDup (keys a) /\ (forall t, In t done -> In t (keys a)) /\
  (forall y ny c, In (y, ny, c) a -> ny = nvl y /\ c = cntE y done).
