Lemma conc_tryBF_eq : forall bc e cands,
  (forall s nvs c, In (s, nvs, c) cands -> nvs = nvl s /\ c = cntE s (subexprs e)) ->
  conc_tryBF bc e (nvl e) cands = conc_tryB bc e (keys cands).
Proof.
