Fixpoint rm_get (m : rmemo) (e : expr) : option (option (Z * Z)) :=
  match m with
  | [] => None
  | (a, r) :: t => if expr_eqbF e a then Some r else rm_get t e
  end.
Lemma rm_get_ok : forall bc m e r, RMOK bc m -> rm_get m e = Some r -> r = erangeB bc e.
