Definition rangeM (bc : bctx) (m : rmemo) (e : expr) : option (Z * Z) * rmemo :=
  if bigE e then
    match rm_get m e with
    | Some r => (r, m)
    | None => let r := erangeBF bc e in (r, (e, r) :: m)
    end
  else (erangeBF bc e, m).
