Lemma to_saddrKB_nolit : forall bc e imm B k, split_lit e = (B, k) -> is_lit B = None ->
  to_saddrKB bc e imm = match concretizeB bc (mkAlu ALU_ADD e (ELit imm)) with Some v => SA (ELit 0) v | None => to_saddr e imm end.
Proof.
