Lemma add_nl0_spec : forall bc c a imm B k, BCOK bc c -> split_lit a = (B, k) -> is_lit B = None ->
  fst (add_nl0 bc c a imm B k) = mkAluKB bc ALU_ADD a (ELit imm) /\ BCOK bc (snd (add_nl0 bc c a imm B k)).
